arguments.cmd:
mkdir -p /app/output && cat > /app/output/index.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f7f8fc;
      --surface: #ffffff;
      --ink: #111827;
      --muted: #667085;
      --hero: #0f172a;
      --coral: #ff6b57;
      --green: #39d98a;
      --yellow: #f9c74f;
      --violet: #7c3aed;
      --ring: #c7d2fe;
      --radius: 18px;
      --shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
      --max: 1160px;
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      color: var(--ink);
      background: var(--bg);
      line-height: 1.5;
    }

    h1, h2, h3, h4 {
      font-family: 'Plus Jakarta Sans', system-ui, sans-serif;
      line-height: 1.15;
      margin: 0;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }

    .container { width: min(var(--max), 92%); margin: 0 auto; }

    .header {
      position: sticky;
      top: 0;
      z-index: 10;
      backdrop-filter: blur(10px);
      background: rgba(247, 248, 252, 0.9);
      border-bottom: 1px solid #e9eaf2;
    }

    .nav {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 74px;
      gap: 1rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.6rem;
      font-weight: 800;
      font-family: 'Plus Jakarta Sans', sans-serif;
      font-size: 1.1rem;
    }

    .brand-badge {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--coral), var(--yellow));
      display: grid;
      place-items: center;
      color: white;
      font-weight: 800;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      color: #475467;
      font-weight: 500;
    }

    .cta-inline {
      display: inline-flex;
      align-items: center;
      gap: .8rem;
    }

    .btn {
      border: 0;
      border-radius: 999px;
      padding: 0.78rem 1.1rem;
      font-weight: 600;
      cursor: pointer;
      font-family: inherit;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
    }

    .btn:hover { transform: translateY(-1px); }

    .btn-dark {
      background: #111827;
      color: white;
      box-shadow: 0 8px 20px rgba(17,24,39,.22);
    }

    .hero-wrap {
      margin: 1.6rem auto 2.5rem;
      background: radial-gradient(circle at 85% 20%, #1f2a44 0%, var(--hero) 55%);
      color: white;
      border-radius: 30px;
      padding: 2.2rem;
      box-shadow: 0 20px 40px rgba(2, 6, 23, 0.26);
      overflow: hidden;
    }

    .hero {
      display: grid;
      gap: 2rem;
      grid-template-columns: 1.1fr .9fr;
      align-items: center;
    }

    .hero h1 {
      font-size: clamp(2rem, 4.8vw, 3.5rem);
      letter-spacing: -0.02em;
    }

    .hero p {
      color: #c6d0e4;
      max-width: 56ch;
      margin: 1rem 0 1.3rem;
    }

    .hero-ctas {
      display: grid;
      gap: .8rem;
      max-width: 360px;
    }

    .btn-sign {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: .7rem;
      border-radius: 14px;
      padding: .95rem 1rem;
      border: 1px solid transparent;
      font-weight: 700;
      font-size: .97rem;
      cursor: pointer;
    }

    .btn-google {
      background: white;
      color: #0f172a;
    }

    .btn-email {
      background: var(--coral);
      color: white;
      box-shadow: 0 12px 25px rgba(255,107,87,.35);
    }

    .btn-sign:hover { transform: translateY(-1px); }

    .pill-row {
      display: flex;
      gap: .7rem;
      overflow-x: auto;
      padding-bottom: .4rem;
      margin-top: 1.4rem;
      scrollbar-width: thin;
    }

    .pill {
      white-space: nowrap;
      border: 1px solid #31405f;
      color: #e2e8f0;
      padding: .55rem .95rem;
      border-radius: 999px;
      font-size: .87rem;
      background: rgba(255,255,255,.04);
    }

    .hero-card {
      background: rgba(255,255,255,.08);
      border: 1px solid rgba(255,255,255,.12);
      border-radius: 24px;
      padding: 1rem;
      backdrop-filter: blur(2px);
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: .8rem;
    }

    .mini {
      background: rgba(10, 18, 38, .8);
      border-radius: 16px;
      padding: .8rem;
      min-height: 98px;
      border: 1px solid rgba(148, 163, 184, .2);
    }

    .section { margin: 3.4rem 0; }
    .section h2 { font-size: clamp(1.5rem, 2.4vw, 2.3rem); margin-bottom: .65rem; }
    .section .lead { color: var(--muted); margin-top: 0; max-width: 68ch; }

    .features {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .feature-card {
      background: var(--surface);
      border-radius: var(--radius);
      padding: 1.25rem;
      box-shadow: var(--shadow);
      border: 1px solid #eceef6;
    }

    .stats-band {
      background: linear-gradient(135deg, #111827, #1f2937);
      border-radius: 22px;
      color: white;
      padding: 1.4rem;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: .9rem;
    }

    .stat {
      background: rgba(255,255,255,.05);
      border: 1px solid rgba(255,255,255,.1);
      border-radius: 14px;
      padding: 1rem;
      text-align: center;
    }

    .stat strong { display: block; font-size: clamp(1.6rem, 2.8vw, 2.25rem); }

    .tabs {
      display: flex;
      gap: .6rem;
      flex-wrap: wrap;
      margin-bottom: 1rem;
    }

    .tab {
      border: 1px solid #d9deeb;
      background: white;
      color: #344054;
      border-radius: 999px;
      padding: .52rem .9rem;
      font-weight: 600;
      cursor: pointer;
    }

    .tab[aria-selected="true"] {
      background: #111827;
      color: white;
      border-color: #111827;
    }

    .course-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .course-card {
      background: white;
      border: 1px solid #eaedf6;
      border-radius: 18px;
      overflow: hidden;
      box-shadow: var(--shadow);
      transition: transform .2s ease, box-shadow .2s ease;
    }

    .course-card:hover {
      transform: translateY(-3px);
      box-shadow: 0 14px 32px rgba(15,23,42,.12);
    }

    .thumb {
      height: 150px;
      display: grid;
      place-items: end start;
      padding: .8rem;
      color: white;
      font-weight: 700;
      font-family: 'Plus Jakarta Sans', sans-serif;
    }

    .course-body { padding: .95rem; }
    .meta { color: #667085; font-size: .88rem; display: flex; justify-content: space-between; gap: .4rem; }

    .feed-grid,
    .testi-grid,
    .teams-grid {
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(3, 1fr);
    }

    .tile {
      background: white;
      border: 1px solid #eceef6;
      border-radius: 16px;
      padding: 1rem;
      box-shadow: var(--shadow);
    }

    .teachers-head {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-bottom: .8rem;
    }

    .carousel-wrap {
      position: relative;
    }

    .carousel-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(220px, 1fr);
      gap: 1rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      padding-bottom: .5rem;
    }

    .teacher-card {
      scroll-snap-align: start;
      background: white;
      border-radius: 18px;
      border: 1px solid #eceef6;
      padding: 1rem;
      box-shadow: var(--shadow);
    }

    .avatar {
      width: 56px;
      height: 56px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      color: white;
      font-weight: 800;
      font-family: 'Plus Jakarta Sans';
      margin-bottom: .6rem;
    }

    .arrow-btn {
      border: 1px solid #d8ddec;
      background: white;
      border-radius: 50%;
      width: 38px;
      height: 38px;
      font-size: 1rem;
      cursor: pointer;
    }

    .faq {
      background: white;
      border: 1px solid #eceef6;
      border-radius: 16px;
      overflow: hidden;
      box-shadow: var(--shadow);
    }

    .faq-item + .faq-item { border-top: 1px solid #eef1f7; }

    .faq-btn {
      width: 100%;
      text-align: left;
      padding: 1rem;
      background: white;
      border: 0;
      font: inherit;
      display: flex;
      justify-content: space-between;
      align-items: center;
      cursor: pointer;
      font-weight: 600;
    }

    .faq-panel {
      display: none;
      padding: 0 1rem 1rem;
      color: #667085;
    }

    .faq-item.active .faq-panel { display: block; }

    footer {
      margin-top: 3.4rem;
      background: #0b1221;
      color: #c6d0e4;
      padding: 2rem 0;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.2fr 1fr 1fr;
      gap: 1rem;
    }

    @media (max-width: 960px) {
      .hero { grid-template-columns: 1fr; }
      .features, .course-grid, .feed-grid, .testi-grid, .teams-grid { grid-template-columns: repeat(2,1fr); }
      .stats-grid { grid-template-columns: repeat(2,1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 640px) {
      .nav-links { display: none; }
      .features, .course-grid, .feed-grid, .testi-grid, .teams-grid, .footer-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .hero-wrap { padding: 1.2rem; }
      .hero-card { padding: .75rem; }
    }
  </style>
</head>
<body>
  <header class="header">
    <div class="container nav">
      <a class="brand" href="index.html">
        <span class="brand-badge">C</span>
        <span>CreativeHub</span>
      </a>
      <nav class="nav-links">
        <a href="index.html">Browse</a>
        <a href="index.html">Sign In</a>
      </nav>
      <div class="cta-inline">
        <a class="btn btn-dark" href="index.html">Sign Up</a>
      </div>
    </div>
  </header>

  <main>
    <section class="container hero-wrap" id="hero">
      <div class="hero">
        <div>
          <h1>Find Your Creative Spark. Learn from World-Class Artists.</h1>
          <p>Take hands-on online classes in illustration, design, animation, video, and more. Join a thriving community of creatives and start your free trial today.</p>
          <div class="hero-ctas">
            <button class="btn-sign btn-google" id="googleSignup">◉ Continue with Google</button>
            <button class="btn-sign btn-email" id="emailSignup">Continue with email</button>
          </div>
          <div class="pill-row" aria-label="Course categories">
            <span class="pill">Graphic Design</span>
            <span class="pill">Illustration</span>
            <span class="pill">Animation</span>
            <span class="pill">Film &amp; Video</span>
            <span class="pill">Freelance</span>
            <span class="pill">UI/UX Design</span>
          </div>
        </div>
        <aside class="hero-card" aria-label="Highlights">
          <div class="hero-grid">
            <div class="mini"><strong>4.8 ★</strong><br/>App Store Rating</div>
            <div class="mini"><strong>425k+</strong><br/>Members Worldwide</div>
            <div class="mini"><strong>30k+</strong><br/>Classes</div>
            <div class="mini"><strong>9k+</strong><br/>Teachers</div>
          </div>
        </aside>
      </div>
    </section>

    <section class="container section" id="features">
      <h2>Everything You Need to Keep Creating</h2>
      <p class="lead">Explore live workshops, short-form classes, and project-based tracks designed to fit your creative routine.</p>
      <div class="features">
        <article class="feature-card"><h3>Project-Based Learning</h3><p>Learn by making with practical assignments and portfolio-ready outcomes.</p></article>
        <article class="feature-card"><h3>Expert Instructors</h3><p>Get guidance from working creatives across design, illustration, and motion.</p></article>
        <article class="feature-card"><h3>Flexible Anywhere Access</h3><p>Stream classes on web and mobile, at your pace, whenever inspiration strikes.</p></article>
      </div>
    </section>

    <section class="container section" id="stats">
      <div class="stats-band">
        <div class="stats-grid">
          <div class="stat"><strong>425k+</strong><span>Active Members</span></div>
          <div class="stat"><strong>30k+</strong><span>On-Demand Classes</span></div>
          <div class="stat"><strong>9k+</strong><span>Creative Teachers</span></div>
          <div class="stat"><strong>4.8</strong><span>App Store Rating</span></div>
        </div>
      </div>
    </section>

    <section class="container section" id="courses">
      <h2>Explore Popular Classes</h2>
      <p class="lead">Switch categories to discover the perfect next course.</p>
      <div class="tabs" role="tablist" aria-label="Course category tabs" id="courseTabs"></div>
      <div class="course-grid" id="courseGrid"></div>
    </section>

    <section class="container section" id="creative-feed">
      <h2>Inside the Creative Feed</h2>
      <p class="lead">Daily inspiration from projects, tips, and process snapshots.</p>
      <div class="feed-grid">
        <article class="tile"><h3>Daily Prompt Challenges</h3><p>Join themed prompt drops to build consistency and creative confidence.</p></article>
        <article class="tile"><h3>Peer Feedback Threads</h3><p>Share your work-in-progress and get actionable critiques from members.</p></article>
        <article class="tile"><h3>Curated Inspiration Boards</h3><p>Save trends in typography, color, and motion to spark new ideas.</p></article>
      </div>
    </section>

    <section class="container section" id="teachers">
      <div class="teachers-head">
        <div>
          <h2>Learn from Creative Experts</h2>
          <p class="lead">Scroll through instructors and explore their specialties.</p>
        </div>
        <div>
          <button class="arrow-btn" id="teacherPrev" aria-label="Previous teachers">←</button>
          <button class="arrow-btn" id="teacherNext" aria-label="Next teachers">→</button>
        </div>
      </div>
      <div class="carousel-wrap">
        <div class="carousel-track" id="teacherTrack"></div>
      </div>
    </section>

    <section class="container section" id="testimonials">
      <h2>What Students Say</h2>
      <div class="testi-grid" id="testimonialsGrid"></div>
    </section>

    <section class="container section" id="teams">
      <h2>Trusted by Creative Teams</h2>
      <div class="teams-grid">
        <article class="tile"><h3>Agencies</h3><p>Upskill design teams with structured learning tracks and shared playlists.</p></article>
        <article class="tile"><h3>Startups</h3><p>Train cross-functional teams in branding, product design, and storytelling.</p></article>
        <article class="tile"><h3>Freelancers</h3><p>Grow your creative business with classes on pricing, pitching, and delivery.</p></article>
      </div>
    </section>

    <section class="container section" id="faq">
      <h2>Frequently Asked Questions</h2>
      <div class="faq" id="faqList"></div>
    </section>
  </main>

  <footer>
    <div class="container footer-grid">
      <div>
        <h3 style="color:#fff">CreativeHub</h3>
        <p>CreativeHub makes high-quality creative education accessible, engaging, and career-ready.</p>
      </div>
      <div>
        <h4 style="color:#fff">Explore</h4>
        <p>Courses<br/>Teachers<br/>Community</p>
      </div>
      <div>
        <h4 style="color:#fff">Get Started</h4>
        <p>Free Trial<br/>Pricing<br/>Download App</p>
      </div>
    </div>
  </footer>

  <script>
    const coursesByCategory = {
      "Featured": [
        { title: "Kickstart your Creativity with Procreate: 20 Fun Drawings for Beginners and Beyond", instructor: "Cat Coquillette", students: "12,581", duration: "2h 45m", color: "linear-gradient(135deg,#ff6b57,#f9c74f)" },
        { title: "Social Media Content Creation in Canva: From Beginner to Advanced", instructor: "Maggie Stara", students: "9,802", duration: "3h 10m", color: "linear-gradient(135deg,#7c3aed,#22d3ee)" },
        { title: "Landscapes: A Free-Flow Watercolour Masterclass", instructor: "Rosalie Haizlett", students: "7,994", duration: "1h 58m", color: "linear-gradient(135deg,#16a34a,#84cc16)" },
        { title: "Figma UI UX Design Advanced: Become a Pro", instructor: "Mizko", students: "16,492", duration: "4h 20m", color: "linear-gradient(135deg,#334155,#0ea5e9)" },
        { title: "How to Draw: A Beginner's Guide", instructor: "Jazza", students: "18,120", duration: "2h 12m", color: "linear-gradient(135deg,#0ea5e9,#2563eb)" },
        { title: "Learn Video Editing With Premiere Pro For Beginners", instructor: "Phil Ebiner", students: "11,044", duration: "3h 35m", color: "linear-gradient(135deg,#f97316,#ef4444)" }
      ],
      "Music": [
        { title: "Songwriting Lab: Hooks, Harmony & Emotion", instructor: "Avery James", students: "6,421", duration: "2h 05m", color: "linear-gradient(135deg,#f43f5e,#fb7185)" },
        { title: "Bedroom Producer: Electronic Beats from Scratch", instructor: "Niko Vega", students: "8,032", duration: "3h 00m", color: "linear-gradient(135deg,#0ea5e9,#22d3ee)" },
        { title: "Vocal Confidence for Creators", instructor: "Mila Raines", students: "5,284", duration: "1h 40m", color: "linear-gradient(135deg,#f59e0b,#f97316)" }
      ],
      "Drawing & Painting": [
        { title: "Ink Fundamentals: Shape, Texture & Contrast", instructor: "Elena Park", students: "7,210", duration: "2h 15m", color: "linear-gradient(135deg,#475569,#94a3b8)" },
        { title: "Modern Watercolor Florals", instructor: "Rosalie Haizlett", students: "10,410", duration: "1h 52m", color: "linear-gradient(135deg,#14b8a6,#34d399)" },
        { title: "Daily Sketching Habit Bootcamp", instructor: "Marco Lu", students: "4,911", duration: "2h 08m", color: "linear-gradient(135deg,#f97316,#fb7185)" }
      ],
      "Marketing": [
        { title: "Brand Storytelling for Creative Businesses", instructor: "Tasha Reid", students: "9,122", duration: "2h 44m", color: "linear-gradient(135deg,#7c3aed,#a855f7)" },
        { title: "Instagram Growth for Artists", instructor: "Maggie Stara", students: "14,581", duration: "1h 55m", color: "linear-gradient(135deg,#ec4899,#f43f5e)" },
        { title: "Content Strategy in 30 Days", instructor: "Lena Torres", students: "6,038", duration: "2h 28m", color: "linear-gradient(135deg,#334155,#6366f1)" }
      ],
      "Animation": [
        { title: "2D Motion Design in After Effects", instructor: "Soren Bell", students: "12,700", duration: "3h 30m", color: "linear-gradient(135deg,#4f46e5,#22d3ee)" },
        { title: "Character Walk Cycles Explained", instructor: "Noa Kim", students: "5,702", duration: "1h 47m", color: "linear-gradient(135deg,#f59e0b,#facc15)" },
        { title: "Storyboard Like a Pro", instructor: "Cam Rivera", students: "4,398", duration: "2h 19m", color: "linear-gradient(135deg,#0f766e,#14b8a6)" }
      ]
    };

    const teachers = [
      { name: "Cat Coquillette", role: "Illustrator", color: "#ff6b57" },
      { name: "Maggie Stara", role: "Digital Designer", color: "#7c3aed" },
      { name: "Noa Kim", role: "Animator, Product Designer", color: "#22c55e" },
      { name: "Mizko", role: "Graphic Designer", color: "#f59e0b" },
      { name: "Rosalie Haizlett", role: "Watercolor Artist", color: "#0ea5e9" },
      { name: "Soren Bell", role: "Motion Graphics Artist", color: "#ef4444" }
    ];

    const testimonials = [
      { quote: "Joining CreativeHub was the best learning decision I've ever made.", name: "Leah M.", title: "Freelance Illustrator" },
      { quote: "Real-world skills without the financial burden of full-time school.", name: "Jordan T.", title: "Design Student" },
      { quote: "It's the one subscription I can't imagine not having.", name: "Priya K.", title: "UI Designer" },
      { quote: "The community feedback helps me level up my skills every week.", name: "Andre R.", title: "Motion Artist" }
    ];

    const faqItems = [
      { q: "What is CreativeHub?", a: "CreativeHub is an online learning platform with project-based classes taught by expert creatives across design, illustration, animation, and more." },
      { q: "What is included in my membership?", a: "Membership includes unlimited access to classes, community discussions, downloadable resources, and guided project tracks." },
      { q: "What can I learn?", a: "You can learn graphic design, illustration, animation, film and video, UI/UX, freelancing, and broader creative business skills." },
      { q: "What happens after my trial is over?", a: "After the trial ends, your selected plan begins automatically. You can cancel any time before renewal from account settings." },
      { q: "Can I teach on the platform?", a: "Yes. CreativeHub accepts instructor applications from experienced practitioners with a clear curriculum and sample lesson quality." }
    ];

    const tabsEl = document.getElementById('courseTabs');
    const gridEl = document.getElementById('courseGrid');
    const categories = Object.keys(coursesByCategory);
    let activeCategory = categories[0];

    function renderTabs() {
      tabsEl.innerHTML = '';
      categories.forEach((category) => {
        const b = document.createElement('button');
        b.className = 'tab';
        b.textContent = category;
        b.setAttribute('role', 'tab');
        b.setAttribute('aria-selected', String(category === activeCategory));
        b.addEventListener('click', () => {
          activeCategory = category;
          renderTabs();
          renderCourses();
        });
        tabsEl.appendChild(b);
      });
    }

    function renderCourses() {
      const list = coursesByCategory[activeCategory] || [];
      gridEl.innerHTML = list.map((course) => `
        <article class="course-card">
          <div class="thumb" style="background:${course.color}">
            <span>${activeCategory}</span>
          </div>
          <div class="course-body">
            <h3 style="font-size:1rem; margin-bottom:.55rem">${course.title}</h3>
            <p style="margin:.3rem 0 .6rem; color:#475467">${course.instructor}</p>
            <div class="meta"><span>${course.students} students</span><span>${course.duration}</span></div>
          </div>
        </article>
      `).join('');
    }

    function renderTeachers() {
